const state={receive:'tBRL',mode:'pay',amount:0,period:'24h',simMode:'pay',simAmount:0,quote:null,history:[]};
const price=5,fee=.01;const balances={USDT:200,tBRL:0};
const fmt=(n,d=2)=>n.toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
const payAsset=()=>state.receive==='tBRL'?'USDT':'tBRL';
function compute(amount,mode='pay'){const rate=state.receive==='tBRL'?price:1/price;const pay=mode==='pay'?amount:amount/(rate*(1-fee));const gross=pay*rate;return {pay,gross,cost:gross*fee,net:gross*(1-fee),rate};}
function check(){const q=compute(state.amount,state.mode),minimum=payAsset()==='USDT'?20:100;if(!Number.isFinite(q.pay)||state.amount<0||state.amount>1000000)return {valid:false,message:'Informe uma quantidade válida até 1.000.000.'};if(q.pay<minimum)return {valid:false,message:`Operação demonstrativa requer no mínimo ${fmt(minimum)} ${payAsset()}.`};if(q.pay>balances[payAsset()]+1e-8)return {valid:false,message:'O valor supera o saldo de teste disponível.'};return {valid:true,message:'Quantidade válida para gerar uma cotação de demonstração.'};}
const amountInput=(id,value,symbol)=>`<div class="otc-amount"><label class="sr-only" for="${id}">${id==='otc-amount'?'Quantidade da operação':'Quantidade para simular'}</label><input type="number" id="${id}" min="0" max="1000000" step="0.01" value="${value}" inputmode="decimal"><span>${symbol}</span></div>`;
function token(symbol,selected=false,interactive=false){return `<${interactive?'button type="button"':'div'} class="otc-token ${selected?'selected':''}" ${interactive?`data-receive="${symbol}" aria-pressed="${selected}" id="receive-${symbol}"`:''}><strong>${symbol}</strong><span><i aria-hidden="true"></i>${symbol==='USDT'?'USDT (Ethereum)':'Real tokenizado'}</span><small>${symbol==='USDT'?'ETHEREUM':'MOONBEAM'}</small></${interactive?'button':'div'}>`;}
function modeButtons(sim=false){const mode=sim?state.simMode:state.mode;return `<div class="otc-segmented" aria-label="${sim?'Modo da simulação':'Modo de preenchimento'}">${[['pay',sim?'Simular quanto pagar':'Definir quanto pagar'],['receive',sim?'Simular quanto receber':'Definir quanto receber']].map(([key,label])=>`<button type="button" ${sim?'data-sim-mode':'data-otc-mode'}="${key}" aria-pressed="${mode===key}" class="${mode===key?'active':''}"><span aria-hidden="true">${key==='pay'?'↗':'↙'}</span>${label}</button>`).join('')}</div>`;}
function sparkline(){const shift=['24h','7D','30D','90D'].indexOf(state.period);const points=Array.from({length:28},(_,i)=>`${i*7},${48-Math.sin(i*.9+shift)*7-i*.8-Math.sin(i*2.2)*5}`).join(' ');return `<svg class="otc-sparkline" viewBox="0 0 195 60" role="img" aria-label="Série de preços fictícia, período ${state.period}"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
function simulation(){if(!Number.isFinite(state.simAmount)||state.simAmount<=0||state.simAmount>1000000)return '<p class="otc-hint">Digite um valor para ver a simulação. Nenhuma ordem será enviada.</p>';const q=compute(state.simAmount,state.simMode);return `<div class="otc-sim-lines"><div><span>Você pagaria</span><strong>${fmt(q.pay)} ${payAsset()}</strong></div><div><span>Custo fictício (1%)</span><strong>${fmt(q.cost)} ${state.receive}</strong></div><div><span>Você receberia</span><strong>${fmt(q.net)} ${state.receive}</strong></div></div>`;}
function quotePane(icon){const q=state.quote;if(!q)return `<div class="otc-waiting"><span class="otc-wait-icon">${icon('swap')}</span><h3>Aguardando cotação</h3><p>Informe o ativo e a quantidade para gerar um cenário de preço.</p><small>Preços fixos e ilustrativos. Sem conexão com o mercado.</small></div>`;if(q.status==='done')return `<div class="otc-waiting"><span class="otc-wait-icon">${icon('check')}</span><h3>Simulação concluída</h3><p>A revisão foi adicionada ao histórico demonstrativo.</p><small>Nenhum saldo foi alterado e nenhuma ordem foi enviada.</small><button class="btn btn-primary mt20" data-otc-new>Simular outra operação</button></div>`;return `<div class="otc-quote-content"><div class="otc-quote-status"><span>Preço ilustrativo reservado</span><strong id="otc-timer" role="timer" aria-label="Tempo restante da cotação demonstrativa">${Math.max(0,Math.ceil((q.expiresAt-Date.now())/1000))}s</strong></div><div class="otc-conversion"><span>Você recebe no cenário</span><strong>${fmt(q.net)} <small>${q.receive}</small></strong></div>${[['Você paga',fmt(q.pay)+' '+q.payAsset],['Taxa de conversão fictícia',fmt(q.rate,4)+' '+q.receive+'/'+q.payAsset],['Valor bruto',fmt(q.gross)+' '+q.receive],['Custo fictício (1%)',fmt(q.cost)+' '+q.receive]].map(([k,v])=>`<div class="otc-quote-line"><span>${k}</span><strong>${v}</strong></div>`).join('')}<div class="otc-notice">Este preço não foi consultado ou travado em um provedor. O cronômetro demonstra o prazo de revisão de uma cotação.</div><label class="checkbox"><input type="checkbox" id="otc-accept"><span>Entendo que esta é uma simulação e que nenhum recurso será movimentado.</span></label><button class="btn btn-primary full mt20" id="otc-confirm" disabled>Concluir simulação ${icon('check')}</button><p class="otc-hint" id="otc-expiration" aria-live="polite">${Date.now()>=q.expiresAt?'Cenário expirado. Solicite uma nova cotação demonstrativa.':''}</p></div>`;}
function history(icon){if(!state.history.length)return `<div class="otc-history-empty">${icon('clock')}<p>Nenhuma operação simulada ainda.</p></div>`;return `<div class="otc-history-table"><table><caption class="sr-only">Histórico fictício da mesa OTC</caption><thead><tr><th>Data e hora</th><th>Você pagaria</th><th>Você receberia</th><th>Status</th></tr></thead><tbody>${state.history.map(q=>`<tr><td>${new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(q.date)}</td><td>${fmt(q.pay)} ${q.payAsset}</td><td>${fmt(q.net)} ${q.receive}</td><td>Simulação concluída</td></tr>`).join('')}</tbody></table></div>`;}
function content(icon){const pay=payAsset(),currency=state.mode==='pay'?pay:state.receive,validation=check();return `<header class="otc-heading"><div class="row"><a class="otc-back" href="#/app/carteira" aria-label="Voltar à carteira">${icon('arrow')}</a><div><span class="eyebrow">Negociação assistida</span><h1>Mesa OTC</h1><p>Configure, compare e revise cada condição antes do próximo passo.</p></div></div><span class="otc-demo-label">${icon('shield')}Ambiente de simulação</span></header><div class="otc-grid"><section class="otc-panel"><h2 class="otc-panel-title"><span>01</span>Configurar operação</h2><div class="otc-section-label"><strong>↙ Você recebe</strong><span>Ativo de destino</span></div><div class="otc-tokens" role="group" aria-label="Ativo a receber">${token('tBRL',state.receive==='tBRL',true)}${token('USDT',state.receive==='USDT',true)}</div><div class="otc-divider">${icon('swap')}</div><div class="otc-section-label"><strong>↗ Você paga com</strong><span>Ativo de origem</span></div><div class="otc-tokens">${token(pay,true)}</div>${modeButtons()}<div class="otc-available"><span>${icon('wallet')}Saldo de teste disponível</span><strong>${fmt(balances[pay])} ${pay}</strong></div>${amountInput('otc-amount',state.amount,currency)}<div class="otc-percentages" role="group" aria-label="Percentual do saldo de teste">${[25,50,75,100].map(n=>`<button type="button" data-otc-percent="${n}">${n}%</button>`).join('')}</div><div class="otc-validation ${validation.valid?'valid':'invalid'}" id="otc-validation" role="status">${icon('info')}<span>${validation.message}</span></div><button class="btn btn-primary full" id="otc-request" ${validation.valid?'':'disabled'}>${icon('chart')}Solicitar cotação demonstrativa</button><section class="otc-market"><div class="otc-section-label"><strong>Cenário de mercado <span class="otc-illustrative">Ilustrativo</span></strong><div class="otc-periods" role="group" aria-label="Período do gráfico">${['24h','7D','30D','90D'].map(p=>`<button data-otc-period="${p}" aria-pressed="${state.period===p}" class="${state.period===p?'active':''}">${p}</button>`).join('')}</div></div><div class="row between"><div><span class="otc-hint">tBRL/USDT</span><strong class="otc-market-value">0,200000</strong></div>${sparkline()}</div></section><section class="otc-mini-simulator"><div class="otc-section-label"><strong>${icon('doc')}Simular operação</strong><span>Sem enviar ordem</span></div>${modeButtons(true)}${amountInput('otc-sim-amount',state.simAmount,state.simMode==='pay'?pay:state.receive)}<div id="otc-sim-result" aria-live="polite">${simulation()}</div></section></section><section class="otc-panel otc-quote-panel"><h2 class="otc-panel-title"><span>02</span>Cotação de demonstração</h2><div id="otc-result">${quotePane(icon)}</div></section></div><section class="otc-panel otc-history"><h2>Histórico de operações</h2><div id="otc-history">${history(icon)}</div></section>`;}
export function renderOtc(icon){return `<div class="otc-desk" data-otc>${content(icon)}</div>`;}
export function mountOtc(root,icon){const desk=root.querySelector('[data-otc]');if(!desk)return ()=>{};const controller=new AbortController(),{signal}=controller;
 const refresh=()=>{const focus=document.activeElement?.id;desk.innerHTML=content(icon);if(focus)document.getElementById(focus)?.focus({preventScroll:true});};
 const sync=()=>{state.quote=null;const v=check(),message=desk.querySelector('#otc-validation');message.className='otc-validation '+(v.valid?'valid':'invalid');message.innerHTML=icon('info')+'<span>'+v.message+'</span>';desk.querySelector('#otc-request').disabled=!v.valid;desk.querySelector('#otc-result').innerHTML=quotePane(icon);};
 desk.addEventListener('input',event=>{if(event.target.id==='otc-amount'){state.amount=Number(event.target.value);sync();}if(event.target.id==='otc-sim-amount'){state.simAmount=Number(event.target.value);desk.querySelector('#otc-sim-result').innerHTML=simulation();}},{signal});
 desk.addEventListener('change',event=>{if(event.target.id==='otc-accept'){const valid=state.quote&&Date.now()<state.quote.expiresAt;desk.querySelector('#otc-confirm').disabled=!event.target.checked||!valid;}},{signal});
 desk.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.receive){state.receive=b.dataset.receive;state.amount=0;state.simAmount=0;state.quote=null;refresh();}if(b.dataset.otcMode){state.mode=b.dataset.otcMode;state.amount=0;state.quote=null;refresh();}if(b.dataset.simMode){state.simMode=b.dataset.simMode;state.simAmount=0;refresh();}if(b.dataset.otcPeriod){state.period=b.dataset.otcPeriod;refresh();}if(b.dataset.otcPercent){const pay=balances[payAsset()]*Number(b.dataset.otcPercent)/100;state.amount=Number((state.mode==='pay'?pay:compute(pay).net).toFixed(2));desk.querySelector('#otc-amount').value=state.amount;sync();}if(b.id==='otc-request'&&check().valid){state.quote={...compute(state.amount,state.mode),payAsset:payAsset(),receive:state.receive,expiresAt:Date.now()+30000,status:'pending'};desk.querySelector('#otc-result').innerHTML=quotePane(icon);}if(b.id==='otc-confirm'&&state.quote&&Date.now()<state.quote.expiresAt&&desk.querySelector('#otc-accept')?.checked){state.quote.status='done';state.history.unshift({...state.quote,date:Date.now()});desk.querySelector('#otc-result').innerHTML=quotePane(icon);desk.querySelector('#otc-history').innerHTML=history(icon);}if(b.hasAttribute('data-otc-new')){state.quote=null;desk.querySelector('#otc-result').innerHTML=quotePane(icon);}},{signal});
 const timer=setInterval(()=>{const q=state.quote,timer=desk.querySelector('#otc-timer');if(!q||q.status!=='pending'||!timer)return;const remaining=Math.max(0,Math.ceil((q.expiresAt-Date.now())/1000));timer.textContent=remaining+'s';if(!remaining){desk.querySelector('#otc-confirm').disabled=true;desk.querySelector('#otc-expiration').textContent='Cenário expirado. Solicite uma nova cotação demonstrativa.';}},1000);
 return ()=>{controller.abort();clearInterval(timer);};
}
